import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DPaNRfRs.js";import"./chunks/assets.00tzVH5c.js";var i=JSON.parse(`{"title":"Architecture","description":"In this page we give an architecture overview on how BullMQ is implemented on top of Redis.","frontmatter":{"description":"In this page we give an architecture overview on how BullMQ is implemented on top of Redis."},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1785480634000}`),a={name:`guide/architecture.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><p>In order to use the full potential of Bull queues, it is important to understand the lifecycle of a job. From the moment a producer calls the <a href="https://docs.bullmq.io/api/classes/v6.Queue.html#add" target="_blank" rel="noreferrer"><code>add</code></a> method on a <code>Queue</code> instance, a job enters a lifecycle where it will be in different states, until its completion or failure (although technically a failed job could be retried and get a new lifecycle).</p><figure><img src="/assets/simple-architecture.BKuk0qq_.png" alt="Diagram showing the lifecycle of a job in a queue, including wait, prioritized, delayed, active, completed, and failed states"><figcaption><p>Lifecycle of a job - Queue</p></figcaption></figure><p>When a job is added to a queue it can be in one of three states:</p><ul><li><strong>“wait”</strong>: a waiting list, where all jobs must enter before they can be processed.</li><li><strong>“prioritized”</strong>: implies that a job with higher priority will be processed first.</li><li><strong>“delayed”</strong>: implies that the job is waiting for some timeout or to be promoted for being processed. These jobs are not processed directly, but instead are placed at the beginning of the waiting list, or in a prioritized set, and processed as soon as a worker is idle.</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Note that priorities go from <code>0</code> to <code>2^21</code>, where 0 is the highest priority. This follows a similar standard as processed in Unix (<a href="https://en.wikipedia.org/wiki/Nice_(Unix)" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Nice_(Unix)</a>, where a higher number means less priority).</p></div><p>The next state for a job is the <strong>“active”</strong> state. The active state is represented by a set, and are jobs that are currently being processed (i.e. they are running in the <code>process</code> function explained in the previous chapter). A job can be in the active state for an unlimited amount of time until the process is completed or an exception is thrown so that the job will end in either the <strong>“completed”</strong> or the <strong>“failed”</strong> status.</p><p>Another way to add a job is by the <a href="https://docs.bullmq.io/api/classes/v6.FlowProducer.html#add" target="_blank" rel="noreferrer"><code>add</code></a> method on a flow producer instance.</p><figure><img src="/assets/flow-architecture.D4fl1MnN.png" alt="Diagram showing the lifecycle of a job in a flow producer, including wait, prioritized, delayed, waiting-children, active, completed, and failed states"><figcaption><p>Lifecycle of a job - Flow Producer</p></figcaption></figure><p>When a job is added by a flow producer, it can be in one of three states, it can either be in the <strong>“wait”</strong> or <strong>“prioritized“</strong> or <strong>“delayed“</strong> status, when there aren&#39;t children, or it can be in a <strong>“waiting-children”</strong> status: a waiting-children status implies that the job is waiting for all its children to be completed, however, a waiting-children job will not be processed directly, instead it will be placed at the waiting list or at delayed set (if <code>delay</code> is provided) or at prioritized set (if <code>delay</code> is 0 and <code>priority</code> is greater than 0) as soon as the last child is marked as completed.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};